        Test("live writer activity detected",()=>{using(var g=new ActivityGuard(new[]{settings.Global.GamePath})){File.WriteAllText(Path.Combine(settings.Global.GamePath,"update.tmp"),"updating");Thread.Sleep(150);Block(()=>g.Check());}});
        Test("game running prevents writes and launches",()=>{Reset();string hash=Files.HashFile(vars);var p=new FakePlatform{Game=true};Block(()=>new Engine(settings,state,p).Switch("Global",s=>{},CancellationToken.None).GetAwaiter().GetResult());Assert(p.Starts==0&&Files.HashFile(vars)==hash,"Unsafe change");});
        Test("shutdown timeout prevents language mutation",()=>{Reset();string hash=Files.HashFile(vars);var p=new FakePlatform{Running=true,ExitFails=true};Block(()=>new Engine(settings,state,p).Switch("Global",s=>{},CancellationToken.None).GetAwaiter().GetResult());Assert(p.Starts==0&&Files.HashFile(vars)==hash,"Unsafe timeout");});
        Test("launch failure restores original",()=>{Reset();string hash=Files.HashFile(vars);var p=new FakePlatform{StartFails=true};Block(()=>new Engine(settings,state,p).Switch("Global",s=>{},CancellationToken.None).GetAwaiter().GetResult());Assert(Files.HashFile(vars)==hash&&!File.Exists(Path.Combine(state,"pending-language.json")),"Rollback failed");});
