        Test("cancel in region launch still commits target language and region",()=>{Reset();string hash=Files.HashFile(vars);using(var c=new CancellationTokenSource()){var p=new FakePlatform{Cancellation=c,CancelOnStart=true};var r=new Engine(settings,state,p).Switch("Global",s=>{},c.Token).GetAwaiter().GetResult();Assert(c.IsCancellationRequested&&p.Starts==1&&r.Region=="EU"&&Files.HashFile(vars)!=hash&&!File.Exists(Path.Combine(state,"pending-language.json")),"Irrevocable launch was rolled back or left journal");}});
        Test("cancel during region confirmation still commits target language and region",()=>{Reset();string hash=Files.HashFile(vars);using(var c=new CancellationTokenSource()){var p=new FakePlatform{Cancellation=c,CancelOnDelay=3};var r=new Engine(settings,state,p).Switch("Global",s=>{},c.Token).GetAwaiter().GetResult();Assert(c.IsCancellationRequested&&p.Starts==1&&r.Region=="EU"&&Files.HashFile(vars)!=hash&&!File.Exists(Path.Combine(state,"pending-language.json")),"Confirmation cancellation caused rollback or stranded journal");}});
        Test("UI busy state locks target, region, and interface language",()=>{UiText.SetLanguage("zh-CN");var m=new Sc2Wpf.MainViewModel();m.Initialize("EU","EU");m.SetReady(true);Assert(m.IsGlobal&&m.CanSwitch&&m.CanEditRegion,"Initial state");m.IsChina=true;Assert(!m.CanEditRegion&&m.ActionLabel=="切换到国服","CN state");m.SetBusy(true);m.IsGlobal=true;m.Asia=true;m.UiLanguage="en-US";Assert(m.IsChina&&m.Region=="EU"&&m.UiLanguage=="zh-CN"&&!m.CanSwitch&&!m.CanEditRegion&&m.BusyVisibility==System.Windows.Visibility.Visible&&m.BusyLabel=="正在切换","Busy state allowed a mutable selection or language");m.SetBusy(false);Assert(m.IsIdle&&m.CanSwitch&&m.BusyVisibility==System.Windows.Visibility.Collapsed,"Busy exit did not restore interaction");});
        Test("UI phase advances through non-cancellable busy completion",()=>{UiText.SetLanguage("zh-CN");var m=new Sc2Wpf.MainViewModel();m.SetReady(true);m.SetBusy(true);m.SetPhase(SwitchPhase.Checking);Assert(!m.IsCommitStarted&&m.StepLabel=="阶段 1 / 3"&&m.BusyVisibility==System.Windows.Visibility.Visible,"Checking phase state");m.SetPhase(SwitchPhase.StartingBattleNet);Assert(m.IsCommitStarted&&m.StepLabel=="阶段 3 / 3"&&m.BusyLabel=="正在切换","Launch phase did not show busy completion");m.SetBusy(false);Assert(!m.IsCommitStarted&&m.IsIdle&&m.CanSwitch&&m.BusyVisibility==System.Windows.Visibility.Collapsed,"Completion did not restore interaction");});
        Test("selecting a target does not change current region",()=>{var m=new Sc2Wpf.MainViewModel();m.Initialize("EU","EU");m.IsChina=true;Assert(m.Target=="CN"&&m.CurrentRegion=="外服 · 欧洲","Selection mistaken for current state");m.IsGlobal=true;m.Asia=true;Assert(m.CurrentRegion=="外服 · 欧洲"&&m.Region=="KR","Region preference mistaken for current state");});
        Test("inspection blocks competing actions until complete",()=>{var m=new Sc2Wpf.MainViewModel();m.SetReady(true);m.SetInspecting(true);Assert(!m.CanInspect&&!m.CanSwitch,"Concurrent action allowed");m.SetInspecting(false);Assert(m.CanInspect&&m.CanSwitch,"Controls stay locked");});
        Test("progress and error actions appear in matching states",()=>{var m=new Sc2Wpf.MainViewModel();m.SetBusy(true);m.SetStage(2);Assert(m.ProgressVisibility==System.Windows.Visibility.Visible&&m.StepLabel=="阶段 2 / 3","Progress stage");m.SetBusy(false);m.Status("Failed","Long failure detail","error");Assert(m.ProgressVisibility==System.Windows.Visibility.Collapsed&&m.ErrorVisibility==System.Windows.Visibility.Visible,"Error action missing");m.Status("Ready","Complete");Assert(m.ErrorVisibility==System.Windows.Visibility.Collapsed,"Stale error action");});
